 "content": "def transform(grid):
    """Extend a half-width color bar with color 1 when a full row of that color exists."""
    out = [row[:] for row in grid]
    width = len(out[0]) if out else 0
    full_colors = {row[0] for row in out if row and all(cell == row[0] for cell in row)}
    for row in out:
        if not row:
            continue
        color = row[0]
        if color in full_colors and width % 2 == 0:
            half = width // 2
            if all(cell == color for cell in row[:half]) and all(cell != color for cell in row[half:]):
                row[half:] = [1] * (width - half)
    return out
